from fractions import Fraction
import itertools

def _v2(n):
    if n <= 0:
        raise ValueError('domain violation')
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c

def verify(witness):
    'Pure deterministic check; returns True only if the finite Kuerschak parity claim holds non-vacuously over the witness domain. Fails closed on any anomaly.'
    try:
        d = witness['domain']
        smin = int(d['start_min']); smax = int(d['start_max'])
        lmin = int(d['length_min']); lmax = int(d['length_max'])
        mmax = int(d['multiset_max_size'])
    except Exception:
        return False
    if smin < 2 or lmin < 2 or mmax < 1 or smax < smin or lmax < lmin or mmax > 4:
        return False
    pool = []
    for a in range(smin, smax + 1):
        for L in range(lmin, lmax + 1):
            b = a + L - 1
            rec = sum(Fraction(1, n) for n in range(a, b + 1))
            pool.append(((a, b), rec))
    checked = 0
    for size in range(1, mmax + 1):
        for combo in itertools.combinations_with_replacement(pool, size):
            total = Fraction(0)
            for _, rec in combo:
                total += rec
            if total.denominator != 1:
                continue
            checked += 1
            vals = [_v2(iv[0]) for iv, _ in combo]
            m = max(vals)
            cnt = 0
            for v in vals:
                if v == m:
                    cnt += 1
            if cnt % 2 != 0:
                return False
    if checked == 0:
        return False
    return True

def main():
    result = verify(WITNESS)
    if result is True:
        return 'PASS: %s' % _last_checked
    return 'FAIL'

WITNESS = {
  'domain': {'start_min': 2, 'start_max': 20, 'length_min': 2, 'length_max': 6, 'multiset_max_size': 3}
}

_last_checked = 0
